    @Test
    public void constructor_NoArgs_CreatesEmptyMap() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertEquals(0, config.comments.size());
    }

    @Test
    public void constructor_WorksWithExistingMap() {
        Map<String, List<String>> existingComments = new HashMap<>();
        existingComments.put("path1", Arrays.asList("line1", "line2"));
        CommentsConfiguration config = new CommentsConfiguration(existingComments);
        assertEquals(existingComments, config.comments);
    }

    @Test
    public void setComment_OverwritesExistingEntries() {
        CommentsConfiguration config = new CommentsConfiguration();
        config.setComment("path1", "line1");
        config.setComment("path2", "line2");
        assertEquals(2, config.comments.size());
        assertEquals(Arrays.asList("line1"), config.comments.get("path1"));
        assertEquals(Arrays.asList("line2"), config.comments.get("path2"));
